private final ProductStore products;
private final TransactionRunner transactions;

public ProductService(ProductStore products, TransactionRunner transactions) {
    this.products = products;
    this.transactions = transactions;
}

/**
 * Vender = guardar la venta + descontar el stock. Las dos cosas o ninguna:
 * si no alcanza el stock, el rollback borra también la venta ya insertada.
 */
public Sale registerSale(int productId, int quantity) {
    if (quantity <= 0) {
        throw new IllegalArgumentException("La cantidad debe ser mayor que cero");
    }
    return transactions.inTransaction((txProducts, txSales) -> {
        Product product = txProducts.findById(productId)
                .orElseThrow(() -> new ProductNotFoundException(productId));
        BigDecimal total = product.price().multiply(BigDecimal.valueOf(quantity));
        Sale sale = txSales.save(new Sale(null, productId, quantity, total));
        if (!txProducts.decreaseStock(productId, quantity)) {
            throw new InsufficientStockException(product.name(), product.stock(), quantity);
        }
        return sale;
    });
}

public interface ProductStore {

    /** Inserta y devuelve el producto con el id que asignó la base. */
    Product save(Product product);

    /** @return false si no existe un producto con ese id. */
    boolean update(Product product);

    /** @return false si no existe un producto con ese id. */
    boolean delete(int id);

    Optional<Product> findById(int id);

    List<Product> findAll();

    /** Resta stock solo si alcanza. @return false si no había stock suficiente. */
    boolean decreaseStock(int id, int quantity);
}

public interface SaleStore {

    /** Inserta y devuelve la venta con el id que asignó la base. */
    Sale save(Sale sale);
}

public <T> T inTransaction(Work<T> work) {
    try (Connection connection = dataSource.getConnection()) {
        connection.setAutoCommit(false);              // desde aquí nada se guarda solo
        try {
            T result = work.run(new JdbcProductRepository(connection),
                                new JdbcSaleRepository(connection));
            connection.commit();                      // todo salió bien: se guarda todo
            return result;
        } catch (RuntimeException e) {
            connection.rollback();                    // algo falló: no se guarda nada
            throw e;
        } finally {
            connection.setAutoCommit(true);           // la conexión vuelve limpia al pool
        }
    } catch (SQLException e) {
        throw new DataAccessException("Falló la transacción: " + e.getMessage(), e);
    }
}

public boolean decreaseStock(int id, int quantity) {
    // La condición stock >= ? evita vender lo que no hay, aunque dos cajas vendan a la vez
    String sql = "UPDATE products SET stock = stock - ? WHERE id = ? AND stock >= ?";
    return withConnection("descontar el stock", connection -> {
        try (PreparedStatement ps = connection.prepareStatement(sql)) {
            ps.setInt(1, quantity);
            ps.setInt(2, id);
            ps.setInt(3, quantity);
            return ps.executeUpdate() == 1;
        }
    });
}

