@Repository
public class JdbcProductRepository implements ProductStore {

    private final JdbcClient jdbc;

    // Spring Boot crea el JdbcClient con el DataSource (HikariCP) y lo pasa por constructor
    public JdbcProductRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<Product> findById(int id) {
        return jdbc.sql("SELECT id, name, price, stock FROM products WHERE id = ?")
                .param(id)
                .query(Product.class)   // columnas id, name, price, stock -> record Product
                .optional();
    }

    @Override
    public boolean decreaseStock(int id, int quantity) {
        return jdbc.sql("UPDATE products SET stock = stock - ? WHERE id = ? AND stock >= ?")
                .params(quantity, id, quantity)
                .update() == 1;
    }
}

@Service
public class ProductService {

    private final ProductStore products;
    private final SaleStore sales;

    public ProductService(ProductStore products, SaleStore sales) {
        this.products = products;
        this.sales = sales;
    }

    // Una sola transacción: commit al salir, rollback si sale una RuntimeException
    @Transactional
    public Sale registerSale(int productId, int quantity) {
        if (quantity <= 0) {
            throw new IllegalArgumentException("La cantidad debe ser mayor que cero");
        }
        Product product = products.findById(productId)
                .orElseThrow(() -> new ProductNotFoundException(productId));
        BigDecimal total = product.price().multiply(BigDecimal.valueOf(quantity));
        Sale sale = sales.save(new Sale(null, productId, quantity, total));
        if (!products.decreaseStock(productId, quantity)) {
            throw new InsufficientStockException(product.name(), product.stock(), quantity);
        }
        return sale;
    }
}
